// 전: 시간·네트워크가 안에 박혀 테스트 불가
async function expire(order) {
  if (Date.now() > order.deadline) await db.markExpired(order.id);
}

// 후: 의존을 인자로 (기본값 = 운영 동작 유지)
async function expire(order, { now = Date.now, markExpired = db.markExpired } = {}) {
  if (now() > order.deadline) await markExpired(order.id);
}
// 운영: expire(order)  ·  테스트: expire(order, { now: () => T, markExpired: fn })

function decide(order, now): Action[] {          // 순수 — 테스트 쉬움
  if (now > order.deadline) return [{ type: 'expire', id: order.id }];
  return [];
}
async function execute(actions) {                 // IO — 얇다
  for (const a of actions) if (a.type === 'expire') await db.markExpired(a.id);
}
// 조립: execute(decide(order, Date.now()))
// 어려운 판단은 decide 에 몰려 값으로 테스트 (functional core, imperative shell)
